import fs from 'node:fs';
import path from 'node:path';

import type { DocsExample } from '../app/docs/example-types';
import { headingIdOf } from '../lib/heading-id';
import { sentenceOfSlug } from '../lib/sentence-of-slug';

const ROOT = path.join(__dirname, '..');
const DOCS_DIR = path.join(ROOT, 'app/docs');
const GENERATED_DIR = path.join(DOCS_DIR, '_generated');
const GENERATED_NOTICE =
  '// Generated by scripts/build-registry.ts from the docs pages. Do not edit.';

const PREVIEW_TAG = '<ComponentCodePreview';
const FENCE = '```';
const HEADING_PATTERN = /^(#{1,4})\s+(.+?)\s*$/;
const IMPORT_PATTERN = /import\s+(?:(\w+)|\{([^}]*)\})\s+from\s+'([^']+)'/g;
const COMPONENT_PATTERN = /component=\{<(\w+)\s*\/>\}/;
const FILE_PATH_PATTERN = /filePath=(?:'([^']+)'|"([^"]+)")/;
const REPLAY_PATTERN = /\bhasReTrigger\b(?!=\{false\})/;
const MARKDOWN_MARKS = /[`*_[\]]/;
const MAX_BLOCK_LINES = 12;

type DocsImport = {
  importedName: string;
  importPath: string;
  isDefault: boolean;
};

type DocsExampleSource = DocsExample & {
  localName: string;
  importedName: string;
  importPath: string;
  isDefault: boolean;
};

export type DocsPage = {
  slug: string;
  pageTitle: string;
  examples: DocsExampleSource[];
};

function sortedAlphabetically(values: string[]) {
  return [...values].sort((first, second) => first.localeCompare(second));
}

function plainTextOf(heading: string) {
  return heading.replace(MARKDOWN_MARKS, '').trim();
}

function anchorOf(heading: string) {
  const hasMarkdown = MARKDOWN_MARKS.test(heading);
  if (hasMarkdown) {
    return '';
  }
  return headingIdOf(heading);
}

function resolvedImportPathOf(importPath: string, slug: string) {
  if (importPath.startsWith('./')) {
    const file = importPath.slice(2);
    return `@/app/docs/${slug}/${file}`;
  }
  if (importPath.startsWith('@/')) {
    return importPath;
  }
  throw new Error(
    `The docs page ${slug} imports ${importPath}, which is not local`
  );
}

function namedImportsOf(specifiers: string, importPath: string) {
  const parts = specifiers.split(',').map((part) => part.trim());
  const named = parts.filter((part) => part.length > 0);
  return named.map((part) => {
    const [importedName, localName = importedName] = part.split(/\s+as\s+/);
    return { localName, importedName, importPath, isDefault: false };
  });
}

function importsOf(text: string, slug: string) {
  const imports = new Map<string, DocsImport>();
  for (const match of text.matchAll(IMPORT_PATTERN)) {
    const [, defaultName, specifiers, rawPath] = match;
    const importPath = resolvedImportPathOf(rawPath, slug);
    if (defaultName) {
      imports.set(defaultName, {
        importedName: defaultName,
        importPath,
        isDefault: true,
      });
      continue;
    }
    for (const named of namedImportsOf(specifiers, importPath)) {
      imports.set(named.localName, {
        importedName: named.importedName,
        importPath: named.importPath,
        isDefault: false,
      });
    }
  }
  return imports;
}

function isBlockEnd(line: string, block: string) {
  const trimmed = line.trim();
  if (trimmed === '/>') {
    return true;
  }
  const endsTag = trimmed.endsWith('/>');
  const hasFilePath = block.includes('filePath=');
  return endsTag && hasFilePath;
}

function blockAt(lines: string[], start: number, slug: string) {
  const collected: string[] = [];
  for (let index = start; index < lines.length; index += 1) {
    collected.push(lines[index]);
    const block = collected.join('\n');
    if (isBlockEnd(lines[index], block)) {
      return block;
    }
    if (collected.length >= MAX_BLOCK_LINES) {
      break;
    }
  }
  throw new Error(
    `An example of the docs page ${slug} does not end near line ${start + 1}`
  );
}

function pageTitleOf(lines: string[], slug: string) {
  let isInFence = false;
  for (const line of lines) {
    if (line.trimStart().startsWith(FENCE)) {
      isInFence = !isInFence;
      continue;
    }
    const match = HEADING_PATTERN.exec(line);
    const isTopHeading = match !== null && match[1] === '#';
    if (!isInFence && isTopHeading) {
      return plainTextOf(match[2]);
    }
  }
  return sentenceOfSlug(slug);
}

function exampleOf(
  block: string,
  heading: string,
  slug: string,
  pageTitle: string,
  imports: Map<string, DocsImport>
): DocsExampleSource {
  const component = COMPONENT_PATTERN.exec(block);
  const filePath = FILE_PATH_PATTERN.exec(block);
  if (!component || !filePath) {
    throw new Error(
      `An example of the docs page ${slug} has no component or no filePath`
    );
  }
  const localName = component[1];
  const fullPath = filePath[1] ?? filePath[2];
  if (!fullPath.endsWith('.tsx')) {
    throw new Error(
      `The example ${fullPath} of the docs page ${slug} is not a .tsx file`
    );
  }
  const imported = imports.get(localName);
  if (!imported) {
    throw new Error(
      `The docs page ${slug} uses ${localName} without importing it`
    );
  }
  const example = path.basename(fullPath, '.tsx');
  const title = plainTextOf(heading) || sentenceOfSlug(example);
  return {
    slug,
    example,
    title,
    pageTitle,
    anchor: anchorOf(heading),
    isReplayable: REPLAY_PATTERN.test(block),
    localName,
    importedName: imported.importedName,
    importPath: imported.importPath,
    isDefault: imported.isDefault,
  };
}

function examplesOf(text: string, slug: string) {
  const lines = text.split('\n');
  const imports = importsOf(text, slug);
  const pageTitle = pageTitleOf(lines, slug);
  const examples: DocsExampleSource[] = [];
  const seen = new Set<string>();
  let heading = '';
  let isInFence = false;
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.trimStart().startsWith(FENCE)) {
      isInFence = !isInFence;
      continue;
    }
    if (isInFence) {
      continue;
    }
    const headingMatch = HEADING_PATTERN.exec(line);
    if (headingMatch) {
      heading = headingMatch[2];
      continue;
    }
    if (!line.includes(PREVIEW_TAG)) {
      continue;
    }
    const block = blockAt(lines, index, slug);
    const example = exampleOf(block, heading, slug, pageTitle, imports);
    if (seen.has(example.example)) {
      console.warn(`The docs page ${slug} shows ${example.example} twice`);
      continue;
    }
    seen.add(example.example);
    examples.push(example);
  }
  return { pageTitle, examples };
}

export function collectDocsPages() {
  const entries = fs.readdirSync(DOCS_DIR, { withFileTypes: true });
  const folders = entries.filter((entry) => entry.isDirectory());
  const slugs = folders.map((folder) => folder.name);
  const publicSlugs = slugs.filter((slug) => !slug.startsWith('_'));
  const pages: DocsPage[] = [];
  for (const slug of sortedAlphabetically(publicSlugs)) {
    const pagePath = path.join(DOCS_DIR, slug, 'page.mdx');
    if (!fs.existsSync(pagePath)) {
      continue;
    }
    const text = fs.readFileSync(pagePath, 'utf8');
    const { pageTitle, examples } = examplesOf(text, slug);
    if (examples.length > 0) {
      pages.push({ slug, pageTitle, examples });
    }
  }
  return pages;
}

function importLineOf(example: DocsExampleSource) {
  if (example.isDefault) {
    return `import ${example.localName} from '${example.importPath}';`;
  }
  const isRenamed = example.importedName !== example.localName;
  if (isRenamed) {
    return `import { ${example.importedName} as ${example.localName} } from '${example.importPath}';`;
  }
  return `import { ${example.localName} } from '${example.importPath}';`;
}

function previewModuleOf(page: DocsPage) {
  const imports = page.examples.map(importLineOf);
  const rows = page.examples.map(
    (example) => `  '${example.example}': ${example.localName},`
  );
  return [
    GENERATED_NOTICE,
    "import type { ComponentType } from 'react';",
    '',
    ...imports,
    '',
    'export const previews: Record<string, ComponentType> = {',
    ...rows,
    '};',
    '',
  ].join('\n');
}

function exampleDataOf(example: DocsExampleSource): DocsExample {
  return {
    slug: example.slug,
    example: example.example,
    title: example.title,
    pageTitle: example.pageTitle,
    anchor: example.anchor,
    isReplayable: example.isReplayable,
  };
}

function indexModuleOf(pages: DocsPage[]) {
  const examples = pages.flatMap((page) => page.examples.map(exampleDataOf));
  const data = JSON.stringify(examples, null, 2);
  return [
    GENERATED_NOTICE,
    "import type { DocsExample } from '@/app/docs/example-types';",
    '',
    `export const docsExamples: DocsExample[] = ${data};`,
    '',
  ].join('\n');
}

function previewHostsModuleOf(pages: DocsPage[]) {
  const hosts = pages.map(
    (page) =>
      `  '${page.slug}': dynamic(() => import('./${page.slug}').then(previewHostOf)),`
  );
  return [
    GENERATED_NOTICE,
    "'use client';",
    '',
    "import dynamic from 'next/dynamic';",
    "import type { ComponentType } from 'react';",
    '',
    'import {',
    '  previewHostOf,',
    '  type PreviewHostProps,',
    "} from '@/app/_site/preview-host';",
    '',
    'export const previewHosts: Record<string, ComponentType<PreviewHostProps>> = {',
    ...hosts,
    '};',
    '',
  ].join('\n');
}

function removeStaleModules(keep: Set<string>) {
  for (const name of fs.readdirSync(GENERATED_DIR)) {
    if (!keep.has(name)) {
      fs.rmSync(path.join(GENERATED_DIR, name));
    }
  }
}

export function writeDocsModules(pages: DocsPage[]) {
  fs.mkdirSync(GENERATED_DIR, { recursive: true });
  const written = new Set<string>(['index.ts', 'preview-hosts.tsx']);
  for (const page of pages) {
    const name = `${page.slug}.ts`;
    fs.writeFileSync(path.join(GENERATED_DIR, name), previewModuleOf(page));
    written.add(name);
  }
  fs.writeFileSync(path.join(GENERATED_DIR, 'index.ts'), indexModuleOf(pages));
  fs.writeFileSync(
    path.join(GENERATED_DIR, 'preview-hosts.tsx'),
    previewHostsModuleOf(pages)
  );
  removeStaleModules(written);
}
